INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Brauchen Container immer Docker?', 2, '[{"text": "Nein", "correct": true, "because": "Andere wie Podman existieren"}, {"text": "Ja", "correct": false, "because": "Docker ist nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für die Orchestrierung mehrerer Container?', 3, '[{"text": "Kubernetes", "correct": true, "because": "Skalierung und Verwaltung"}, {"text": "Docker", "correct": false, "because": "Nur Laufzeit"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Docker für Entwickler nützlich?', 5, '[{"text": "Portabilität", "correct": true, "because": "Überall gleich lauffähig"}, {"text": "Leichtgewichtigkeit", "correct": true, "because": "Wenig Overhead"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Nicht automatisch sicher"}, {"text": "Komplexe Einrichtung", "correct": false, "because": "Relativ einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kubernetes verwaltet Container. b) Docker erstellt Hypervisors.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Docker für Container"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Docker?', 4, '[{"text": "Image-Konfiguration", "correct": false, "because": "Kern der Container"}, {"text": "Laufzeitumgebung", "correct": false, "because": "Muss kompatibel sein"}, {"text": "Lokale GPU-Leistung", "correct": true, "because": "Meist serverbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kubernetes ohne Docker läuft?', 2, '[{"text": "Ja", "correct": true, "because": "Mit anderen Runtimes wie CRI-O"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend Docker nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für Kubernetes?', 3, '[{"text": "Automatische Skalierung", "correct": true, "because": "Passt sich Last an"}, {"text": "Einfache GUI", "correct": false, "because": "Sekundär"}, {"text": "Lokale Speicherung", "correct": false, "because": "Verteiltes System"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Docker?', 5, '[{"text": "Konsistenz", "correct": true, "because": "Gleiche Umgebung überall"}, {"text": "Schnelle Bereitstellung", "correct": true, "because": "Images schnell gestartet"}, {"text": "Hohe Hardwarelast", "correct": false, "because": "Leichtgewicht"}, {"text": "Einfache Verwaltung", "correct": false, "because": "Kann komplex werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Docker isoliert Anwendungen. b) Kubernetes erstellt Container-Images. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Docker macht Images"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Container in einem kleinen Projekt?', 4, '[{"text": "Docker Images", "correct": false, "because": "Basis der Container"}, {"text": "Laufzeitumgebung", "correct": false, "because": "Docker oder ähnliches nötig"}, {"text": "Kubernetes-Cluster", "correct": true, "because": "Überdimensioniert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Container schwerer als VMs?', 2, '[{"text": "Nein", "correct": true, "because": "Leichter durch OS-Freigabe"}, {"text": "Ja", "correct": false, "because": "VMs haben mehr Overhead"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für Kubernetes in der Produktion wichtig?', 4, '[{"text": "Hochverfügbarkeit", "correct": true, "because": "Ausfallsicherheit"}, {"text": "Load Balancing", "correct": true, "because": "Verteilt Traffic"}, {"text": "Lokale Speicherung", "correct": false, "because": "Verteilte Systeme"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Docker weniger sicher ist als VMs. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger Isolation als VMs"}, {"text": "Nein", "correct": false, "because": "Mit Konfiguration sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für Docker in der Entwicklung?', 3, '[{"text": "Schnelle Builds", "correct": true, "because": "Effiziente Iteration"}, {"text": "Maximale Sicherheit", "correct": false, "because": "Sekundär in Dev"}, {"text": "Komplexe Orchestrierung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kubernetes skaliert automatisch. b) Docker braucht Hypervisors.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, keine Hypervisors nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Kubernetes?', 5, '[{"text": "Hohe Komplexität", "correct": true, "because": "Schwierige Verwaltung"}, {"text": "Ressourcenbedarf", "correct": true, "because": "Cluster benötigt Leistung"}, {"text": "Geringere Kosten", "correct": false, "because": "Setup kann teuer sein"}, {"text": "Einfache Nutzung", "correct": false, "because": "Lernkurve hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Docker für einen Webserver unwichtig?', 3, '[{"text": "Image-Größe", "correct": false, "because": "Beeinflusst Startzeit"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Zugriff entscheidend"}, {"text": "Lokale GPU", "correct": true, "because": "Webserver braucht keine Grafik"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Container schneller als VMs?', 3, '[{"text": "Ja", "correct": true, "because": "Weniger Overhead"}, {"text": "Nein", "correct": false, "because": "VMs schwerer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kubernetes für ein Einzelprojekt nötig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Docker allein oft genug"}, {"text": "Ja", "correct": false, "because": "Überdimensioniert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für eine Microservices-Architektur?', 4, '[{"text": "Kubernetes", "correct": true, "because": "Orchestriert viele Container"}, {"text": "Docker allein", "correct": false, "because": "Fehlt Skalierung"}, {"text": "Manuelle Verwaltung", "correct": false, "because": "Zu komplex"}]');
